/// <summary>
/// MPJ_3338_AMEXCustomerPaymentProcessing -Vpotula
/// Controller class for customizing the customer statement as per AMEX proposal requirement.
/// </summary>
class METAMEXCustAccountStmtExtController extends CustAccountStatementExtController
{
    str                 metReportCompany;
    JournalId           metJournalId;
    CustPaymMode        metPaymMode;    
 
}

Method.Source:
protected void processParty(Query _query, DirPartyRecId _party, container _selectedCompanyList)
{
    super( _query,
          _party,
          [metReportCompany]);
}

    /// <summary>
    /// Applying customer and company range
    /// </summary>
    /// <param name = "_query">Base query.</param>
    /// <param name = "_custAccount">Customer account</param>
    public void metUpdateBaseQuery(Query           _query,
                                    CustAccount     _custAccount)
    {
        CustTable custTable;
        QueryBuildDataSource qbds = _query.dataSourceTable(tableNum(CustTable));
        str rangeStr;

        _query.allowCrossCompany(true);
        _query.addCompanyRange(metReportCompany);
        SysQuery::findOrCreateRange(qbds, fieldNum(CustTable, AccountNum)).value(_custAccount);
        if (this.parmArgs() && this.parmArgs().record() && this.parmArgs().record().TableId == tableNum(CustTable))
        {
            custTable = CustTable::findRecId(this.parmArgs().record().RecId);
            this.parmContract().parmPrintGiro(custTable.GiroTypeAccountStatement);
            rangeStr = queryValue(custTable.AccountNum);
            SysQuery::findOrCreateRange(qbds, fieldNum(CustTable, AccountNum)).value(rangeStr);
        }
    }

/// <summary>
/// Initialize default parameters
/// </summary>
/// <param name = "_args">Arguments to process statement.</param>
public void metInitParms(Args _args)
{
    this.parmArgs(_args);
    this.parmReportName(PrintMgmtDocType::construct(PrintMgmtDocumentType::CustAccountStatement).getDefaultReportFormat());
    this.parmShowDialog(false);
    this.parmLoadFromSysLastValue(false);
}

    public str parmMETSelectedCompany(str _company = metReportCompany)
    {
        metReportCompany = _company;

        return metReportCompany;
    }

public JournalId parmMETJournalId(JournalId _metJournalId = metJournalId)
{
    metJournalId = _metJournalId;
    
    return metJournalId;
}

public CustPaymMode parmMETPaymMode(CustPaymMode _metPaymMode = metPaymMode)
{
    metPaymMode = _metPaymMode;
    
    return metPaymMode;
}

    /// <summary>
    /// Determines whether the specified transaction should be included on the statement.
    /// </summary>
    /// <param name="_trans">
    /// The transaction.
    /// </param>
    /// <returns>
    /// true if the transaction should be included on the statement; otherwise, false.
    /// </returns>
    /// <remarks>
    /// This method relies on the transactions amounts being adjusted for the statement end date.
    /// </remarks>
    protected boolean includeOnStatement(CustTrans _trans)
    {
        boolean ret;

        ret = super(_trans);

        if (ret)
        {
            ret = _trans.PaymMode == metPaymMode ? true: false;
        }
        
        return ret;
    }
